def verify():
    assert 2 ** 2 + 2 + 1 == 7 and abs(math.sqrt(21) - 4.583) < 0.001 and 280 // 7 == 40
    assert abs(40 * math.log10(2) - 12.04) < 0.01 and abs(120 / 3.6 * 3.5e9 / 3e8 - 388.9) < 0.1
    assert 12 * 15 == 180 and abs(1 / 2 ** 3 - 0.125) < 1e-12 and abs(1000 / 30 - 33.33) < 0.01
    assert abs(10 ** ((130 - 128) / 37.6) - 1.130) < 0.001 and abs(3 * math.sqrt(3) / 2 - 2.598) < 0.001 and abs(550e3 / 3e8 * 1e3 - 1.833) < 0.001


if __name__ == "__main__":
    verify()
    write_subject(SUBJECT, U)
